/**
 * One conversation, live: its transcript, the answer being written and the tools running, its cost;
 * and what an operator does to it (SPEC §5): a message that steers the run, an abort, a reset.
 */

import { ArrowLeft, Loader2, RotateCcw, Send, Square, Wrench } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Textarea } from "@/components/ui/textarea";
import { ErrorNote } from "@/components/pikit/error-note";
import { type Message, MessageView } from "@/components/pikit/message";
import { api, type ApiConversation, type ApiPage, type ApiResetResponse, type ApiSendResponse, type ApiTranscriptEntry, post, useApi } from "@/lib/api";
import { formatCost, formatTokens } from "@/lib/format";
import { Link, navigate } from "@/lib/router";
import { useLive } from "./live";
import { Status } from "./list";

const PAGE = 50;

/** The transcript's latest page, read again when the conversation changes, and older pages on demand. */
function useTranscript(id: string, changes: number) {
  const latest = useApi<ApiPage<ApiTranscriptEntry>>(`/conversations/${encodeURIComponent(id)}/transcript?limit=${PAGE}`);
  const [older, setOlder] = useState<ApiTranscriptEntry[]>([]);
  const [cursor, setCursor] = useState<string | null>();
  const { reload } = latest;

  useEffect(() => {
    if (changes === 0) return;
    const timer = setTimeout(reload, 250);
    return () => clearTimeout(timer);
  }, [changes, reload]);

  const next = cursor === undefined ? latest.data?.next : (cursor ?? undefined);
  const loadOlder = async () => {
    if (next === undefined) return;
    const page = await api<ApiPage<ApiTranscriptEntry>>(`/conversations/${encodeURIComponent(id)}/transcript?limit=${PAGE}&cursor=${encodeURIComponent(next)}`);
    setOlder((items) => [...items, ...page.items]);
    setCursor(page.next ?? null);
  };

  // Newest first from the API; shown oldest first.
  const seen = new Set<string>();
  const entries = [...(latest.data?.items ?? []), ...older].filter((entry) => !seen.has(entry.id) && seen.add(entry.id)).reverse();
  return { entries, error: latest.error, hasOlder: next !== undefined, loadOlder };
}

function Actions({ conversation, busy }: { conversation: ApiConversation; busy: boolean }) {
  const [error, setError] = useState<Error>();
  const [working, setWorking] = useState(false);
  const actionable = conversation.current === true;
  const path = `/conversations/${encodeURIComponent(conversation.conversationId)}`;

  const run = async (action: () => Promise<void>) => {
    setWorking(true);
    setError(undefined);
    try {
      await action();
    } catch (thrown) {
      setError(thrown instanceof Error ? thrown : new Error(String(thrown)));
    } finally {
      setWorking(false);
    }
  };

  return (
    <div className="flex flex-col items-end gap-2">
      <div className="flex gap-2">
        <Button variant="outline" size="sm" disabled={!actionable || !busy || working} onClick={() => void run(() => post(`${path}/abort`))}>
          <Square /> Abort run
        </Button>
        <AlertDialog>
          <AlertDialogTrigger asChild>
            <Button variant="outline" size="sm" disabled={!actionable || working}>
              <RotateCcw /> Reset
            </Button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Reset this conversation?</AlertDialogTitle>
              <AlertDialogDescription>
                {conversation.key} starts again with an empty history. This conversation is kept and stays readable here; a run still going finishes in it.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={() =>
                  void run(async () => {
                    const reset = await post<ApiResetResponse>(`${path}/reset`);
                    navigate(`/conversations/${encodeURIComponent(reset.conversationId)}`, { replace: true });
                  })
                }
              >
                Reset
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>
      {error !== undefined && <ErrorNote error={error} title="The action failed" />}
    </div>
  );
}

function Composer({ conversation, busy }: { conversation: ApiConversation; busy: boolean }) {
  const [text, setText] = useState("");
  const [sending, setSending] = useState(false);
  const [note, setNote] = useState<string>();
  const [error, setError] = useState<Error>();

  if (conversation.current !== true) {
    return (
      <p className="text-sm text-muted-foreground">
        {conversation.current === false ? "A reset left this conversation behind: it can be read, not talked to." : "No message has reached this conversation yet."}
      </p>
    );
  }

  const send = async () => {
    if (text.trim() === "") return;
    setSending(true);
    setError(undefined);
    try {
      const sent = await post<ApiSendResponse>(`/conversations/${encodeURIComponent(conversation.conversationId)}/messages`, {
        text,
        requestId: `ui:${crypto.randomUUID()}`,
        whenBusy: "steer",
      });
      setText("");
      setNote(sent.admission === "queued" ? "Sent: it joins the run going at its next step." : "Sent: a run started.");
    } catch (thrown) {
      setError(thrown instanceof Error ? thrown : new Error(String(thrown)));
    } finally {
      setSending(false);
    }
  };

  return (
    <div className="space-y-2">
      <div className="flex items-end gap-2">
        <Textarea
          value={text}
          placeholder={busy ? "Steer the run going…" : "Talk to the agent…"}
          className="min-h-11"
          onChange={(event) => setText(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) void send();
          }}
        />
        <Button onClick={() => void send()} disabled={sending || text.trim() === ""}>
          {sending ? <Loader2 className="animate-spin" /> : <Send />} Send
        </Button>
      </div>
      <p className="text-xs text-muted-foreground">
        {note ?? `Your message joins the conversation: its answer also goes to ${conversation.key}'s chat. ⌘/Ctrl+Enter sends.`}
      </p>
      {error !== undefined && <ErrorNote error={error} title="Not sent" />}
    </div>
  );
}

export function ConversationPage({ params }: { params: Record<string, string> }) {
  const id = params.id ?? "";
  const live = useLive(id);
  const summary = useApi<ApiConversation>(`/conversations/${encodeURIComponent(id)}`);
  const transcript = useTranscript(id, live.changes);
  const bottom = useRef<HTMLDivElement>(null);
  const { reload } = summary;

  useEffect(() => {
    if (live.changes === 0) return;
    const timer = setTimeout(reload, 250);
    return () => clearTimeout(timer);
  }, [live.changes, live.busy, reload]);

  const messages = transcript.entries.flatMap((entry) => entry.messages as Message[]);
  useEffect(() => {
    bottom.current?.scrollIntoView({ block: "end" });
  }, [messages.length, live.partial, live.tools.length]);

  const conversation = summary.data;
  if (summary.error !== undefined) return <ErrorNote error={summary.error} title="This conversation cannot be read" />;
  if (conversation === undefined) return <p className="text-muted-foreground">Loading…</p>;

  return (
    <div className="mx-auto flex max-w-4xl flex-col gap-4">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="space-y-1">
          <Link to="/conversations" className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground">
            <ArrowLeft className="size-3.5" /> Conversations
          </Link>
          <h1 className="text-xl font-semibold">{conversation.key ?? conversation.conversationId}</h1>
          <div className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
            {conversation.agent !== undefined && <Badge variant="outline">{conversation.agent}</Badge>}
            <Status conversation={{ ...conversation, busy: live.busy }} />
            <span className="tabular-nums">
              {formatCost(conversation.usage)} · {formatTokens(conversation.usage.totalTokens)} tokens
            </span>
            <span className="flex items-center gap-1">
              <span className={`size-2 rounded-full ${live.connected ? "bg-emerald-500" : "bg-muted-foreground/40"}`} />
              {live.connected ? "live" : "reconnecting"}
            </span>
          </div>
        </div>
        <Actions conversation={conversation} busy={live.busy} />
      </div>

      <Card>
        <CardContent className="space-y-4">
          {transcript.hasOlder && (
            <Button variant="ghost" size="sm" className="w-full" onClick={() => void transcript.loadOlder()}>
              Load earlier messages
            </Button>
          )}
          {transcript.error !== undefined && <ErrorNote error={transcript.error} />}
          {messages.map((message, i) => (
            <MessageView key={i} message={message} />
          ))}
          {live.partial !== undefined && <MessageView message={live.partial} streaming />}
          {live.tools.map((tool) => (
            <div key={tool.callId} className="rounded-md border border-dashed p-3 text-sm">
              <div className="flex items-center gap-2 text-muted-foreground">
                <Loader2 className="size-3.5 animate-spin" /> <Wrench className="size-3.5" /> {tool.name} running
              </div>
              {tool.output !== "" && <pre className="mt-2 max-h-48 overflow-auto font-mono text-xs whitespace-pre-wrap">{tool.output}</pre>}
            </div>
          ))}
          {messages.length === 0 && live.partial === undefined && <p className="py-6 text-center text-muted-foreground">No messages yet.</p>}
          <div ref={bottom} />
        </CardContent>
      </Card>

      <Composer conversation={conversation} busy={live.busy} />
    </div>
  );
}

import { MessagesSquare } from "lucide-react";
import { defineView } from "@/lib/views";
import { ConversationPage } from "./conversation";
import { ConversationsPage } from "./list";

export default defineView({
  id: "conversations",
  title: "Conversations",
  icon: MessagesSquare,
  requires: ["agent.observe"],
  order: 10,
  pages: [
    { path: "/conversations", component: ConversationsPage },
    { path: "/conversations/:id", component: ConversationPage },
  ],
});

import { useCallback, useEffect, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { ErrorNote } from "@/components/pikit/error-note";
import { api, type ApiConversation, type ApiPage } from "@/lib/api";
import { formatAgo, formatCost } from "@/lib/format";
import { navigate } from "@/lib/router";

const PAGE = 100;
/** At most this many pages are read: the runtime lists in creation order, so the latest are on the last page. */
const MAX_PAGES = 10;

/**
 * Every conversation (up to MAX_PAGES pages), read again every `everyMs`. The runtime lists them in
 * creation order (`agent.observe`), so all pages are read and sorted here by activity.
 */
function useAllConversations(everyMs: number) {
  const [items, setItems] = useState<ApiConversation[]>();
  const [truncated, setTruncated] = useState(false);
  const [error, setError] = useState<Error>();
  const read = useCallback(async () => {
    const all: ApiConversation[] = [];
    let cursor: string | undefined;
    let pages = 0;
    do {
      const page = await api<ApiPage<ApiConversation>>(`/conversations?limit=${PAGE}${cursor === undefined ? "" : `&cursor=${encodeURIComponent(cursor)}`}`);
      all.push(...page.items);
      cursor = page.next;
    } while (cursor !== undefined && ++pages < MAX_PAGES);
    return { all, truncated: cursor !== undefined };
  }, []);

  useEffect(() => {
    let live = true;
    const load = () =>
      read()
        .then(({ all, truncated }) => live && (setItems(all), setTruncated(truncated), setError(undefined)))
        .catch((thrown: unknown) => live && setError(thrown instanceof Error ? thrown : new Error(String(thrown))));
    void load();
    const timer = setInterval(() => void load(), everyMs);
    return () => {
      live = false;
      clearInterval(timer);
    };
  }, [read, everyMs]);

  return { items, truncated, error };
}

export function Status({ conversation }: { conversation: ApiConversation }) {
  if (conversation.current === false) return <Badge variant="outline">left behind</Badge>;
  if (conversation.busy) return <Badge>running</Badge>;
  return <Badge variant="secondary">idle</Badge>;
}

/** Every conversation of the runtime, the most recently active first. */
export function ConversationsPage() {
  const { items: read, truncated, error } = useAllConversations(10_000);
  const items = [...(read ?? [])].sort((a, b) => (b.lastActivity ?? 0) - (a.lastActivity ?? 0));

  return (
    <Card>
      <CardHeader>
        <CardTitle>Conversations</CardTitle>
        <CardDescription>Every conversation of the agent runtime. Open one to follow it live, steer it, stop it or reset it.</CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {error !== undefined && <ErrorNote error={error} />}
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Conversation</TableHead>
              <TableHead>Agent</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Last activity</TableHead>
              <TableHead className="text-right">Cost</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {items.map((conversation) => (
              <TableRow key={conversation.conversationId} className="cursor-pointer" onClick={() => navigate(`/conversations/${encodeURIComponent(conversation.conversationId)}`)}>
                <TableCell className="font-medium">
                  {conversation.key ?? <span className="text-muted-foreground">no message yet</span>}
                  <div className="font-mono text-xs text-muted-foreground">{conversation.conversationId}</div>
                </TableCell>
                <TableCell>{conversation.agent ?? "—"}</TableCell>
                <TableCell>
                  <Status conversation={conversation} />
                </TableCell>
                <TableCell className="text-muted-foreground">{formatAgo(conversation.lastActivity)}</TableCell>
                <TableCell className="text-right tabular-nums">{formatCost(conversation.usage)}</TableCell>
              </TableRow>
            ))}
            {items.length === 0 && read !== undefined && (
              <TableRow>
                <TableCell colSpan={5} className="py-10 text-center text-muted-foreground">
                  No conversations yet: send your agent a message.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
        {truncated && <p className="text-sm text-muted-foreground">Showing the first {PAGE * MAX_PAGES} conversations the runtime keeps.</p>}
      </CardContent>
    </Card>
  );
}

/**
 * A conversation live, from its server-sent events (`GET /admin/api/conversations/:id/events`): whether
 * a run is going, the answer being written, the tools running. The stream starts with a `snapshot`
 * and a client that fell behind gets a new one, so the state is rebuilt from each snapshot, never from
 * a count of events. What is written for good (entries) is read from the transcript again: `changes`
 * counts the times it changed.
 */

import { useEffect, useReducer } from "react";
import { type ApiEvent, follow } from "@/lib/api";
import type { Message } from "@/components/pikit/message";

type Assistant = Extract<Message, { role: "assistant" }>;

export interface RunningTool {
  callId: string;
  name: string;
  output: string;
}

export interface LiveState {
  connected: boolean;
  busy: boolean;
  /** The answer being written. */
  partial?: Assistant;
  tools: RunningTool[];
  /** Bumped whenever the transcript or the cost changed: read them again. */
  changes: number;
}

const INITIAL: LiveState = { connected: false, busy: false, tools: [], changes: 0 };

type Action = { type: "connected" } | { type: "disconnected" } | { type: "event"; event: ApiEvent };

type Change =
  | { type: "text_start" | "thinking_start" | "toolcall_start" | "block"; contentIndex: number; block: Assistant["content"][number] }
  | { type: "text_delta" | "thinking_delta"; contentIndex: number; delta: string }
  | { type: "toolcall_delta" }
  | { type: "message"; message: Assistant };

function applyChanges(partial: Assistant | undefined, changes: Change[]): Assistant | undefined {
  let message = partial;
  for (const change of changes) {
    if (change.type === "message") {
      message = change.message;
      continue;
    }
    if (message === undefined || change.type === "toolcall_delta") continue;
    const content = [...message.content];
    if ("delta" in change) {
      const part = content[change.contentIndex];
      if (part?.type === "text" && change.type === "text_delta") content[change.contentIndex] = { ...part, text: part.text + change.delta };
      if (part?.type === "thinking" && change.type === "thinking_delta") content[change.contentIndex] = { ...part, thinking: part.thinking + change.delta };
    } else {
      content[change.contentIndex] = change.block;
    }
    message = { ...message, content };
  }
  return message;
}

type ToolOutput = { trimStart?: number; append?: string } | { set: string };

function reduce(state: LiveState, action: Action): LiveState {
  if (action.type === "connected") return { ...state, connected: true };
  if (action.type === "disconnected") return { ...state, connected: false };
  const event = action.event;
  const changed = { ...state, changes: state.changes + 1 };
  switch (event.type) {
    case "snapshot": {
      const generation = event.generation as { message?: Assistant } | undefined;
      const tools = (event.tools as { callId: string; name: string; status: string; output?: string }[] | undefined) ?? [];
      return {
        ...changed,
        busy: event.run !== undefined,
        partial: generation?.message,
        tools: tools.filter((tool) => tool.status !== "done").map((tool) => ({ callId: tool.callId, name: tool.name, output: tool.output ?? "" })),
      };
    }
    case "run_start":
      return { ...state, busy: true };
    case "run_end":
      return { ...changed, busy: false, partial: undefined, tools: [] };
    case "message_start": {
      const message = event.message as Message;
      return message.role === "assistant" ? { ...state, partial: message } : state;
    }
    case "message_update":
      return { ...state, partial: applyChanges(state.partial, event.changes as Change[]) };
    case "message_end":
      return { ...changed, partial: undefined };
    case "tool_execution_start":
      return { ...state, tools: [...state.tools, { callId: String(event.toolCallId), name: String(event.toolName), output: "" }] };
    case "tool_execution_update": {
      const output = event.output as ToolOutput | undefined;
      if (output === undefined) return state;
      return {
        ...state,
        tools: state.tools.map((tool) => {
          if (tool.callId !== event.toolCallId) return tool;
          if ("set" in output) return { ...tool, output: output.set };
          return { ...tool, output: tool.output.slice(output.trimStart ?? 0) + (output.append ?? "") };
        }),
      };
    }
    case "tool_execution_end":
      return { ...changed, tools: state.tools.filter((tool) => tool.callId !== event.toolCallId) };
    case "entry_appended":
    case "usage_changed":
      return changed;
    default:
      return state;
  }
}

/** Follows conversation `id` live while mounted, reconnecting after a dropped stream. */
export function useLive(id: string): LiveState {
  const [state, dispatch] = useReducer(reduce, INITIAL);

  useEffect(() => {
    const stop = new AbortController();
    void (async () => {
      while (!stop.signal.aborted) {
        try {
          const started = follow(`/conversations/${encodeURIComponent(id)}/events`, (event) => dispatch({ type: "event", event }), stop.signal);
          dispatch({ type: "connected" });
          await started;
        } catch {
          // Reconnect below.
        }
        dispatch({ type: "disconnected" });
        if (!stop.signal.aborted) await new Promise((resolve) => setTimeout(resolve, 2000));
      }
    })();
    return () => stop.abort();
  }, [id]);

  return state;
}
